// ---------------------------------------------------------------------------
// DA Form 2408-18 (Equipment Inspection List) — AcroForm named-field path.
//
// This PDF template is base64-encoded, WITH its original AcroForm fields
// intact (not flattened) — this is the "PDF already has fillable fields"
// case, so no coordinates are needed at all: values are set directly by
// field name (form.getTextField(name)), same as react_vite_app's approach.
// Field names come straight from the PDF's own AcroForm (inspected with
// pdf-lib) — front page uses one set of base names (InspNo/Item/REF/FREQ/
// NextDue/CompAt), the back page reuses differently-named fields for the
// *same* visual columns (ModelA/ItemA/REF_A/FREQ_A/NextDueA/CompAtA — a
// quirk of how the original form was authored, confirmed by comparing
// against the rendered page text).
// ---------------------------------------------------------------------------
const ACROFORM_2408_18_B64 = "";

const F18_HEADER = {
  page:         "form1[0].Page1[0].Page[0]",
  pageOf:       "form1[0].Page1[0].Pageof[0]",
  nomenclature: "form1[0].Page1[0].Nomen[0]",
  model:        "form1[0].Page1[0].Model[0]",
  serialNumber: "form1[0].Page1[0].SerNo[0]",
};
const F18_COLS = [
  { key: "inspNo",  p1: "InspNo",  p2: "ModelA"   },
  { key: "item",    p1: "Item",    p2: "ItemA"    },
  { key: "ref",     p1: "REF",     p2: "REF_A"    },
  { key: "freq",    p1: "FREQ",    p2: "FREQ_A"   },
  { key: "nextDue", p1: "NextDue", p2: "NextDueA" },
  { key: "compAt",  p1: "CompAt",  p2: "CompAtA"  },
];
const F18_PAGE1_ROWS = 14;
const F18_PAGE2_ROWS = 15;
const F18_ROWS_PER_COPY = F18_PAGE1_ROWS + F18_PAGE2_ROWS; // 29

function f18FieldName(page, base, rowIdx) {
  const suffix = rowIdx === 0 ? "" : "_" + rowIdx;
  const pageKey = page === 0 ? "Page1" : "Page2";
  return `form1[0].${pageKey}[0].${base}${suffix}[0]`;
}

function emptyRow2408_18() {
  return { id: uid(), inspNo: "", item: "", ref: "", freq: "", nextDue: "", compAt: "" };
}

function emptyForm2408_18() {
  return {
    id: uid(),
    header: { nomenclature: "", model: "", serialNumber: "" },
    rows: [emptyRow2408_18()],
  };
}

function cloneForm2408_18(form) {
  return {
    id: uid(),
    header: { ...form.header },
    rows: form.rows.map(r => ({ ...r, id: uid() })),
  };
}

// ---------------------------------------------------------------------------
// AcroForm fill engine for DA 2408-18. Sets named fields directly instead of
// drawing at coordinates — the "PDF already has fields" path. Overflow
// beyond F18_ROWS_PER_COPY works the same way as the coordinate path: extra
// copies of the (still-fillable) template, same shared header on each.
// ---------------------------------------------------------------------------
function setAcroText(form, name, value) {
  if (!value) return;
  let field;
  try { field = form.getTextField(name); } catch { return; } // missing field — skip silently
  const max = field.getMaxLength();
  const str = String(value);
  // pdf-lib throws on a value longer than the field's max length rather
  // than truncating it, so truncate ourselves first.
  field.setText(typeof max === "number" && max > 0 && str.length > max ? str.slice(0, max) : str);
}

async function buildFilledPdf2408_18(form) {
  const { PDFDocument, StandardFonts } = PDFLib;
  const templateBytes = b64ToBytes(ACROFORM_2408_18_B64);

  const outDoc = await PDFDocument.create();
  const rows = form.rows;
  const totalCopies = Math.max(1, Math.ceil(rows.length / F18_ROWS_PER_COPY));

  for (let copyIndex = 0; copyIndex < totalCopies; copyIndex++) {
    const templateDoc = await PDFDocument.load(templateBytes);
    const acroForm = templateDoc.getForm();

    setAcroText(acroForm, F18_HEADER.page, String(copyIndex + 1));
    setAcroText(acroForm, F18_HEADER.pageOf, String(totalCopies));
    setAcroText(acroForm, F18_HEADER.nomenclature, form.header.nomenclature);
    setAcroText(acroForm, F18_HEADER.model, form.header.model);
    setAcroText(acroForm, F18_HEADER.serialNumber, form.header.serialNumber);

    const start = copyIndex * F18_ROWS_PER_COPY;
    const chunk = rows.slice(start, start + F18_ROWS_PER_COPY);
    chunk.forEach((row, i) => {
      const onPage1 = i < F18_PAGE1_ROWS;
      const page = onPage1 ? 0 : 1;
      const rowIdx = onPage1 ? i : i - F18_PAGE1_ROWS;
      for (const col of F18_COLS) {
        const base = onPage1 ? col.p1 : col.p2;
        setAcroText(acroForm, f18FieldName(page, base, rowIdx), row[col.key]);
      }
    });

    const font = await templateDoc.embedFont(StandardFonts.Helvetica);
    acroForm.updateFieldAppearances(font);
    acroForm.flatten();

    const copiedPages = await outDoc.copyPages(templateDoc, templateDoc.getPageIndices());
    copiedPages.forEach(p => outDoc.addPage(p));
  }

  return outDoc.save();
}
